### applyActions

```
function applyActions(actions) {
  let events = 0;
  if (!actions) return events;

  // removeLast
  if (actions.removeLast) {
    events |= removeLastIngredient();
  }

  // take
  if (Array.isArray(actions.take)) {
    for (const id of actions.take) {
      if (state.hand === null && INGREDIENTS[id]) { state.hand = id; }
      // only first effective take; subsequent ignored while hand full
    }
  }

  // placeAt
  if (Array.isArray(actions.placeAt)) {
    for (const station of actions.placeAt) {
      events |= placeAt(station);
    }
  }

  // plate
  if (actions.plate) events |= plateDish();

  // serve
  if (actions.serve) events |= serveDish();

  return events;
}
```

