function dishQualityBonus(recipe, qualities) {
  let sum = 0, count = 0;
  for (const id of recipe.ingredients) {
    const q = id in qualities ? qualities[id] : 2;
    sum += q; count += 1;
  }
  const avg = sum / count;
  if (avg >= 1.9) return 6;      // perfect
  if (avg >= 1) return 2;        // ok
  return -4;                     // burnt included
}
```

