import { INGREDIENTS, prepStation } from './recipes.js';
import { SCREEN_TITLE, SCREEN_PLAY, SCREEN_OVER } from './render.js';

const START_SECONDS = 6;
const PLAY_SECONDS = 35;
const END_LIMIT_SECONDS = 90;

function sameSet(left,right){...}

function autopilotActions(state) {
  const actions = { take: [], placeAt: [], plate: false, serve: false, removeLast: false };
  const order = state.orders[0];
  if (!order) return actions;
  const stove = state.stations.stove;
  const plate = state.boardPlate;
  if (stove.active) {
    if (stove.fire >= STOVE.perfectMin) { actions.placeAt.push('stove'); }
    return actions;
  }
  if (state.hand) { actions.placeAt.push(prepStation(INGREDIENTS[state.hand].prep)); return actions; }
  if (plate.prepped.length > 0) { actions.plate = true; return actions; }
  if (sameSet(plate.raw, order.recipe.ingredients)) { actions.serve = true; return actions; }
  const missing = order.recipe.ingredients.find((id) => !plate.raw.includes(id) && !plate.prepped.includes(id));
  if (missing) { actions.take.push(missing); return actions; }
  return actions;
}

export function stageShot(name, world) {
  world.reset();
  if (name === 'play') {
    run(world, PLAY_SECONDS);
    return { screen: SCREEN_PLAY, best: world.state.score };
  }
  if (name === 'end') {
    run(world, END_LIMIT_SECONDS);
    return { screen: world.state.over ? SCREEN_OVER : SCREEN_PLAY, best: world.state.score };
  }
  // start (and any other name)
  run(world, START_SECONDS);
  return { screen: SCREEN_TITLE, best: 0 };
}

function run(world, seconds) {
  const steps = Math.floor(seconds / STEP);
  for (let i = 0; i < steps; i += 1) {
    if (world.state.over) break;
    world.step(STEP, autopilotActions(world.state));
  }
}
